function validate([s, queries]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10^4 characters.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 pairs.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 2) return 'Each query is a pair [first, second].';
    if (q.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Query values are between 0 and 10^9.';
  }
  return null;
}

