function substringXorQueries(s, queries) {
  const firstSeen = new Map();

  for (let left = 0; left < s.length; left++) {
    if (s[left] === '0') {
      if (!firstSeen.has(0)) firstSeen.set(0, [left, left]);
      continue;
    }
    let value = 0;
    for (let right = left; right < s.length && right < left + 30; right++) {
      value = value * 2 + Number(s[right]);
      if (!firstSeen.has(value)) firstSeen.set(value, [left, right]);
    }
  }

  const answer = [];
  for (const [first, second] of queries) {
    const target = first ^ second;
    answer.push(firstSeen.get(target) ?? [-1, -1]);
  }
  return answer;
}

