function substringXorQueries(s, queries) {
  return queries.map(([first, second]) => {
    const want = BigInt(first ^ second);
    for (let length = 1; length <= s.length; length++)
      for (let start = 0; start + length <= s.length; start++)
        if (BigInt('0b' + s.slice(start, start + length)) === want) return [start, start + length - 1];
    return [-1, -1];
  });
}

