function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(8000, 10000) : int(1, 12);
  const ones = [0.5, 0.1, 0.9, 0.5][int(0, 3)];
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < ones ? '1' : '0';
  // Split a value v into a pair [first, second] with first ^ second == v, both within 0..10^9.
  const pair = (v) => {
    for (let tries = 0; tries < 30; tries++) {
      const first = rand() < 0.5 ? int(0, 63) : int(0, 1e9);
      const second = first ^ v;
      if (second <= 1e9) return [first, second];
    }
    return [0, 0];
  };
  const count = large ? 2000 : int(1, 6);
  const queries = [];
  for (let q = 0; q < count; q++) {
    if (rand() < 0.6) {
      // A value that occurs in s.
      const start = int(0, n - 1);
      const end = Math.min(n - 1, start + int(0, large ? 29 : 5));
      queries.push(pair(parseInt(s.slice(start, end + 1), 2)));
    } else {
      queries.push(rand() < 0.5 ? [int(0, 1e9), int(0, 1e9)] : [int(0, 40), int(0, 40)]);
    }
  }
  return [s, queries];
}
